-- Kithra PostgreSQL representative baseline. NOT the complete 31-table D1 port.
-- Expand from canonical data dictionary; tested schema parity is a developer release requirement.
-- All timestamps UTC; UUIDs externally generated by app when deterministic portability requires.
BEGIN;
CREATE TABLE IF NOT EXISTS users (
  id uuid PRIMARY KEY,
  firebase_subject text NOT NULL UNIQUE,
  email_verified boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','restricted','suspended','deleted')),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS mode_personas (
  id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id),
  mode text NOT NULL CHECK(mode IN ('friendship','dating','matrimony')),
  visibility text NOT NULL DEFAULT 'hidden' CHECK(visibility IN ('hidden','eligible','paused')),
  consent_version text, city_band text,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id,mode)
);
CREATE TABLE IF NOT EXISTS consents (
  id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),
  mode text, purpose_code text NOT NULL, consent_version text NOT NULL,
  granted_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz
);
CREATE TABLE IF NOT EXISTS assessments (
  id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),
  theme_id text NOT NULL, bank_version text NOT NULL, session_seed_version text NOT NULL,
  state text NOT NULL CHECK(state IN ('active','paused','submitted','scored','withdrawn')),
  created_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz
);
CREATE TABLE IF NOT EXISTS responses (
  id uuid PRIMARY KEY, assessment_id uuid NOT NULL REFERENCES assessments(id),
  question_id text NOT NULL, question_version text NOT NULL, answer_json jsonb NOT NULL,
  response_revision bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(assessment_id,question_id)
);
CREATE TABLE IF NOT EXISTS pattern_snapshots (
  id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id),
  assessment_id uuid NOT NULL REFERENCES assessments(id), scoring_version text NOT NULL,
  dimensions_json jsonb NOT NULL, coverage_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), superseded_at timestamptz
);
CREATE TABLE IF NOT EXISTS connection_requests (
  id uuid PRIMARY KEY,source_user uuid NOT NULL REFERENCES users(id),
  target_user uuid NOT NULL REFERENCES users(id), mode text NOT NULL,
  state text NOT NULL CHECK(state IN ('pending','accepted','declined','expired','revoked')),
  created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(source_user<>target_user)
);
CREATE TABLE IF NOT EXISTS user_blocks (
  blocker_user uuid NOT NULL REFERENCES users(id),blocked_user uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_user,blocked_user),
  CHECK(blocker_user<>blocked_user)
);
CREATE TABLE IF NOT EXISTS moderation_cases (
  id uuid PRIMARY KEY, reporter_user uuid REFERENCES users(id), subject_user uuid REFERENCES users(id),
  severity text NOT NULL,status text NOT NULL,assigned_staff uuid,policy_version text,
  created_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz
);
CREATE TABLE IF NOT EXISTS audit_events (
  id uuid PRIMARY KEY, actor_id uuid,actor_type text NOT NULL,action_code text NOT NULL,
  subject_type text NOT NULL,subject_id text,case_id uuid,policy_version text,
  metadata_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mode_eligibility ON mode_personas(mode,visibility,city_band);
CREATE INDEX IF NOT EXISTS idx_audits_actor ON audit_events(actor_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_cases_sla ON moderation_cases(severity,status,due_at);
COMMIT;
